namespace InventoryApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network / database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Hydraulic Press",    Location = "Building A",  LastInspected = new DateTime(2026, 5, 10) },
            new() { Id = 2, Name = "CNC Lathe",          Location = "Building B",  LastInspected = new DateTime(2026, 6, 1) },
            new() { Id = 3, Name = "Forklift #12",       Location = "Warehouse 3", LastInspected = new DateTime(2026, 4, 22) },
            new() { Id = 4, Name = "Overhead Crane",     Location = "Building A",  LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 5, Name = "Welding Station 7",  Location = "Building C",  LastInspected = new DateTime(2026, 6, 20) },
            new() { Id = 6, Name = "Compressor Unit",    Location = "Utility Room", LastInspected = new DateTime(2026, 2, 28) },
            new() { Id = 7, Name = "Band Saw",           Location = "Building B",  LastInspected = new DateTime(2026, 5, 5) },
            new() { Id = 8, Name = "Paint Booth",        Location = "Building D",  LastInspected = new DateTime(2026, 1, 18) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@implements IDisposable
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;
    private PersistingComponentStateSubscription persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        // Try to restore data persisted during prerendering.
        // If found, skip the service call entirely (no double-fetch).
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            items = restored;
        }
        else
        {
            items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("inventory", items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        persistingSubscription.Dispose();
    }
}

